"""Authored manipulation revision, layered over the October 15 decomposition.

No action is generated by guessing a verb from scientific prose. Each manual
step is assigned an explicit interaction interface; selected compound stages
are replaced below. Interface geometry is a separate, fallible binding.
"""
from copy import deepcopy


def step(kind, action, observation, interface=None, when=None):
    d = dict(capability={"M": "manipulation", "P": "perception", "X": "device_process_or_wait", "D": "planning", "A": "analysis"}[kind],
             action=action, completion_observation=observation,
             basis="reconstruction_inference")
    if interface:
        d["interface_id"] = interface
    if when:
        d["condition"] = when
    return d


def m(interface, action, observation, when=None):
    return step("M", action, observation, interface, when)


def p(action, observation):
    return step("P", action, observation)


def x(action, observation):
    return step("X", action, observation)


